const hasDeclaration = (css, selector, property, value) => {
  let matched = false;
  css.walkRules(rule => { if (rule.selector.includes(selector)) rule.walkDecls(property, declaration => { if (declaration.value === value) matched = true; }); });
  return matched;
};
